import os
import json
import pytest
from pathlib import Path

# Mock the scipy.stats.kruskal if not available, or assume it is
# We are testing the logic of T020c

def test_kruskal_wallis_output_exists():
    """Test that the Kruskal-Wallis output file is generated."""
    output_path = Path("data/artifacts/basin_variance_significance.json")
    # This test will pass if the file exists after running code/04_evaluation.py
    # We assume the file is generated by the main() function in 04_evaluation.py
    # If the file doesn't exist, it means the script didn't run or failed.
    # We can't run the script here without data, so we just check existence.
    # In a real integration test, we would run the script and then check.
    assert output_path.exists(), f"Output file {output_path} not found. Run code/04_evaluation.py first."

def test_kruskal_wallis_output_format():
    """Test that the output file has the correct format."""
    output_path = Path("data/artifacts/basin_variance_significance.json")
    if not output_path.exists():
        pytest.skip("Output file not found. Run code/04_evaluation.py first.")

    with open(output_path, 'r') as f:
        data = json.load(f)

    assert 'statistic' in data, "Missing 'statistic' in output"
    assert 'pvalue' in data, "Missing 'pvalue' in output"
    assert 'message' in data, "Missing 'message' in output"

    # Check types
    if data['statistic'] is not None:
        assert isinstance(data['statistic'], (int, float)), "statistic should be a number"
    if data['pvalue'] is not None:
        assert isinstance(data['pvalue'], (int, float)), "pvalue should be a number"